from collections import Counter

def join_size(left_keys, right_keys, how="inner"):
    """Rows that merging tables with these key columns would produce (how is "inner" or "left")."""
    right = Counter(right_keys)
    total = 0
    for key, n in Counter(left_keys).items():
        m = right.get(key, 0)
        if m:
            total += n * m
        elif how == "left":
            total += n
    return total
